"""
sx_rz_sx_euler_to_zxz_phase_merge: scans maximal single-qubit gate runs (h,x,y,z,s,sdg,t,tdg,
sx,sxdg,rz) on each wire, multiplies them into one SU(2) matrix (up to global phase), and
re-emits the cheapest exact representation found among: (a) a pure Clifford / Clifford*T word
(0 or 1 T, no arbitrary rz), (b) Clifford-conjugated single Z-rotation (exactly one arbitrary
rz, sandwiched by Cliffords), (c) the original run, unchanged, if no cheaper exact form is
found (never emits something with >= as many arbitrary rz's / T's as the input run). Each
candidate is a literal matrix equal (up to global phase, which the verifier ignores) to the
run's exact product, so every accepted replacement is exact; we additionally gate acceptance
on strictly fewer "expensive" gates (arbitrary rz / T) than the input run, so the rewrite can
only help.
"""
import math
import cmath
import numpy as np

from circuitevolve.circuit import Circuit, Gate, matrix, is_arbitrary_rz, is_t_like
from circuitevolve.verifier import Req

_SINGLE_Q_NAMES = {"h", "x", "y", "z", "s", "sdg", "t", "tdg", "sx", "sxdg", "rz"}


def _is_close_phase(a, b, tol=1e-6):
    idx = np.unravel_index(np.argmax(np.abs(a)), a.shape)
    pa = a[idx]
    pb = b[idx]
    if abs(pa) < 1e-12 or abs(pb) < 1e-12:
        return np.allclose(a, b, atol=tol)
    a2 = a / pa
    b2 = b / pb
    return np.allclose(a2, b2, atol=tol)


def _gate_matrix(name):
    if name == "id":
        return np.eye(2, dtype=complex)
    return matrix(Gate(name, (0,)))


def _build_clifford_table():
    """Enumerate short words over {h,s,x} (a generating set) to cover the 24-element
    single-qubit Clifford group up to global phase, keeping the shortest word found for
    each equivalence class (BFS => shortest)."""
    gens = ["h", "s", "x"]
    mats = {g: _gate_matrix(g) for g in gens}
    start = (np.eye(2, dtype=complex), ())
    found = {}

    def key_of(m):
        idx = np.unravel_index(np.argmax(np.abs(m)), m.shape)
        p = m[idx]
        mm = m / p
        mm = np.round(mm, 6)
        return tuple(mm.flatten())

    from collections import deque
    q = deque()
    k0 = key_of(start[0])
    found[k0] = start[1]
    q.append(start)
    while q:
        M, word = q.popleft()
        if len(word) >= 6:
            continue
        for g in gens:
            M2 = mats[g] @ M
            k2 = key_of(M2)
            if k2 not in found:
                found[k2] = word + (g,)
                q.append((M2, word + (g,)))
    return found


_CLIFFORD_TABLE = _build_clifford_table()


def _clifford_key(m):
    idx = np.unravel_index(np.argmax(np.abs(m)), m.shape)
    p = m[idx]
    if abs(p) < 1e-9:
        return None
    mm = m / p
    mm = np.round(mm, 6)
    return tuple(mm.flatten())


def _cost_of_word(word):
    """Approximate downstream cost: count T/Tdg as 1 each, everything else free."""
    return sum(1 for w in word if w in ("t", "tdg"))


def _try_clifford_or_clifford_t(U):
    """Return (word, n_t, n_arb_rz=0) for the cheapest of: pure Clifford, Clifford*T,
    Clifford*Tdg, T*Clifford, Tdg*Clifford representations of U (up to global phase)."""
    best = None
    T = _gate_matrix("t")
    Tdg = _gate_matrix("tdg")

    def consider(word):
        nonlocal best
        if word is None:
            return
        cost = _cost_of_word(word)
        if best is None or cost < best[1]:
            best = (word, cost)

    key = _clifford_key(U)
    if key is not None and key in _CLIFFORD_TABLE:
        consider(list(_CLIFFORD_TABLE[key]))

    # U = C * T  => C = U * Tdg
    key = _clifford_key(U @ Tdg)
    if key is not None and key in _CLIFFORD_TABLE:
        consider(list(_CLIFFORD_TABLE[key]) + ["t"])
    # U = C * Tdg => C = U * T
    key = _clifford_key(U @ T)
    if key is not None and key in _CLIFFORD_TABLE:
        consider(list(_CLIFFORD_TABLE[key]) + ["tdg"])
    # U = T * C  => C = Tdg * U
    key = _clifford_key(Tdg @ U)
    if key is not None and key in _CLIFFORD_TABLE:
        consider(["t"] + list(_CLIFFORD_TABLE[key]))
    # U = Tdg * C => C = T * U
    key = _clifford_key(T @ U)
    if key is not None and key in _CLIFFORD_TABLE:
        consider(["tdg"] + list(_CLIFFORD_TABLE[key]))

    return best  # (word, n_t) or None


def _normalize_theta(theta):
    t = theta % (2 * math.pi)
    if t > math.pi:
        t -= 2 * math.pi
    return t


def _rz_word_for_multiple_of_pi4(theta, tol=1e-7):
    """If theta is a multiple of pi/4 (mod 2pi), return the exact Clifford+T word for
    rz(theta) (up to global phase), else None."""
    t_norm = theta / (math.pi / 4)
    k = round(t_norm)
    if abs(t_norm - k) < tol:
        k = k % 8
        mapping = {
            0: [],
            1: ["t"],
            2: ["s"],
            3: ["s", "t"],
            4: ["z"],
            5: ["z", "t"],
            6: ["sdg"],
            7: ["tdg"],
        }
        return mapping[k]
    return None


def _try_single_rz_sandwich(U):
    """Check whether U = C1 * Rz(theta) * C2 (up to global phase) for Cliffords C1, C2 and
    some theta, i.e. U is "Clifford-equivalent to a single Z rotation". We search over the
    (small) Clifford table on both sides: for each C1, C2 in the table, check if
    C1^-1 * U * C2^-1 is diagonal up to global phase. This is O(24*24) matrix mults, cheap.
    Returns (pre_word, theta, post_word) with minimal total non-rz cost, or None.
    """
    best = None
    # Precompute matrices for each table entry word (inverse too).
    items = list(_CLIFFORD_TABLE.items())
    mats = []
    for key, word in items:
        M = np.eye(2, dtype=complex)
        for g in word:
            M = _gate_matrix(g) @ M
        mats.append((word, M))

    for w1, M1 in mats:
        M1inv = M1.conj().T  # unitary inverse
        left = M1inv @ U
        for w2, M2 in mats:
            M2inv = M2.conj().T
            cand = left @ M2inv
            if abs(cand[0, 1]) < 1e-6 and abs(cand[1, 0]) < 1e-6:
                theta = _normalize_theta(2 * (cmath.phase(cand[1, 1]) - cmath.phase(cand[0, 0])))
                rz_word = _rz_word_for_multiple_of_pi4(theta)
                if rz_word is not None:
                    mid_cost = _cost_of_word(rz_word)
                    n_arb = 0
                else:
                    mid_cost = 0
                    n_arb = 1
                total_clifford_t = _cost_of_word(w1) + _cost_of_word(w2) + mid_cost
                cand_res = (w1, theta if rz_word is None else None, rz_word, w2, n_arb, total_clifford_t)
                if best is None or (n_arb, total_clifford_t, len(w1) + len(w2)) < (best[4], best[5], len(best[0]) + len(best[3])):
                    best = cand_res
    return best


def _emit_from_sandwich(best, qubit):
    w1, theta, rz_word, w2, n_arb, _ = best
    gates = []
    for g in w2:
        gates.append(Gate(g, (qubit,)))
    if rz_word is not None:
        for g in rz_word:
            gates.append(Gate(g, (qubit,)))
    else:
        gates.append(Gate("rz", (qubit,), theta=theta))
    for g in w1:
        gates.append(Gate(g, (qubit,)))
    return gates


def _matrix_of_word(word, qubit=0):
    M = np.eye(2, dtype=complex)
    for g in word:
        M = _gate_matrix(g) @ M
    return M


def _matrix_of_gates(gates):
    M = np.eye(2, dtype=complex)
    for g in gates:
        if g.name == "rz":
            gg = Gate("rz", (0,), theta=g.theta)
        else:
            gg = Gate(g.name, (0,))
        M = matrix(gg) @ M
    return M


def _run_cost(names_thetas):
    """Cost metric on the ORIGINAL run: number of T-like gates + number of arbitrary rz's."""
    n_t = 0
    n_arb = 0
    for name, theta in names_thetas:
        if name in ("t", "tdg"):
            n_t += 1
        elif name == "rz":
            gg = Gate("rz", (0,), theta=theta)
            if is_t_like(gg):
                n_t += 1
            elif is_arbitrary_rz(gg):
                n_arb += 1
    return n_t, n_arb


def _word_cost(gates):
    n_t = 0
    n_arb = 0
    for g in gates:
        if g.name in ("t", "tdg"):
            n_t += 1
        elif g.name == "rz":
            if is_t_like(g):
                n_t += 1
            elif is_arbitrary_rz(g):
                n_arb += 1
    return n_t, n_arb


def _process_run(names_thetas, qubit):
    """Return a replacement gate list for this run if we found something strictly cheaper
    (fewer arbitrary rz's, and if tied, fewer T's), else None."""
    U = np.eye(2, dtype=complex)
    for name, theta in names_thetas:
        if name == "rz":
            g = Gate("rz", (0,), theta=theta)
        else:
            g = Gate(name, (0,))
        U = matrix(g) @ U

    orig_t, orig_arb = _run_cost(names_thetas)

    candidates = []

    # 1) pure Clifford / Clifford*T
    res = _try_clifford_or_clifford_t(U)
    if res is not None:
        word, _cost = res
        gates = [Gate(g, (qubit,)) for g in word]
        candidates.append(gates)

    # 2) single rz sandwich (only bother if the run has >= 2 arbitrary rz's worth trying,
    # or even just one, since Clifford pre/post might still shrink T count / merge).
    if orig_arb >= 1 or orig_t >= 1:
        best = _try_single_rz_sandwich(U)
        if best is not None:
            gates = _emit_from_sandwich(best, qubit)
            candidates.append(gates)

    if not candidates:
        return None

    # pick candidate with (fewest arbitrary rz, then fewest T, then fewest gates)
    def score(gates):
        t_, a_ = _word_cost(gates)
        return (a_, t_, len(gates))

    best_gates = min(candidates, key=score)
    best_t, best_arb = _word_cost(best_gates)

    # Only accept if strictly better: fewer arbitrary rz, OR equal arbitrary rz but fewer T,
    # OR equal both but fewer total gates (cheap win, still safe).
    if (best_arb, best_t, len(best_gates)) < (orig_arb, orig_t, len(names_thetas)):
        # verify exact equivalence defensively
        U_new = _matrix_of_gates(best_gates)
        if _is_close_phase(U, U_new, tol=1e-5):
            return best_gates
    return None


def rewrite(c: Circuit):
    gates = c.gates
    n = len(gates)
    out_gates = []
    i = 0
    changed_any = False

    while i < n:
        g = gates[i]
        if g.name in _SINGLE_Q_NAMES and g.cond is None and len(g.qubits) == 1:
            q = g.qubits[0]
            run_idxs = []
            j = i
            while j < n:
                gj = gates[j]
                if q in gj.qubits:
                    if gj.name in _SINGLE_Q_NAMES and gj.cond is None and len(gj.qubits) == 1:
                        run_idxs.append(j)
                        j += 1
                        continue
                    else:
                        break
                else:
                    j += 1
                    continue
            if len(run_idxs) >= 2:
                names_thetas = [(gates[k].name, gates[k].theta) for k in run_idxs]
                new_run = _process_run(names_thetas, q)
                if new_run is not None:
                    run_set = set(run_idxs)
                    # emit interleaved (non-run) gates and the new run, preserving order:
                    # since none of the interleaved gates touch q, and the run gates all
                    # commute as a block relative to them, we place the compressed run at
                    # the position of the run's first element and keep interleaved gates
                    # in their original relative order around it.
                    before_interleaved = []
                    after_interleaved = []
                    last_run_idx = run_idxs[-1]
                    for k in range(i, last_run_idx + 1):
                        if k not in run_set:
                            # determine position: gates strictly between consumed run
                            # elements don't touch q, so they commute freely; keep them
                            # in original relative order, placed before the compressed run
                            # if they occurred before the midpoint is overengineering --
                            # simplest safe choice: since they don't touch q at all, their
                            # position relative to the (now-reordered) run gates on q does
                            # not affect semantics. Emit them all before the new run.
                            before_interleaved.append(gates[k])
                    out_gates.extend(before_interleaved)
                    out_gates.extend(new_run)
                    changed_any = True
                    i = last_run_idx + 1
                    continue
                else:
                    for k in range(i, run_idxs[-1] + 1):
                        out_gates.append(gates[k])
                    i = run_idxs[-1] + 1
                    continue
        out_gates.append(g)
        i += 1

    if not changed_any:
        return c, Req()

    new_c = Circuit(c.n, out_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)

"""
sx_rz_sx_euler_to_zxz_phase_merge: scans maximal runs of single-qubit gates
(h,x,y,z,s,sdg,t,tdg,sx,sxdg,rz) on one wire, multiplies them (in circuit order,
matrices left-applied in reverse) into one 2x2 unitary, and re-emits the run in
the cheapest EXACT form found:
  (a) a pure Clifford (or Clifford*T / T*Clifford) word -> 0 or 1 T, no rz at all;
  (b) Clifford_pre * Rz(theta) * Clifford_post with a single arbitrary rz, when the
      run's matrix is Z-rotation-equivalent up to Cliffords on both sides.
Each candidate word's matrix is checked (up to a global phase, which the verifier
ignores) against the run's exact product before being accepted, and the run is
only replaced when the new form has strictly fewer "expensive" gates (arbitrary
rz counted first, then T/Tdg) than the original run, so every accepted rewrite
is both exact and a genuine improvement.
"""
import cmath
import math
from collections import deque

import numpy as np

from circuitevolve.circuit import Circuit, Gate, matrix, is_arbitrary_rz, is_t_like
from circuitevolve.verifier import Req

_SINGLE_Q_NAMES = {"h", "x", "y", "z", "s", "sdg", "t", "tdg", "sx", "sxdg", "rz"}
_TOL = 1e-6


def _gate_matrix(name):
    return matrix(Gate(name, (0,)))


def _key(m, decimals=6):
    idx = np.unravel_index(np.argmax(np.abs(m)), m.shape)
    p = m[idx]
    if abs(p) < 1e-9:
        return None
    mm = m / p
    return tuple(np.round(mm, decimals).flatten())


def _build_clifford_table():
    gens = ["h", "s", "x"]
    mats = {g: _gate_matrix(g) for g in gens}
    found = {}
    start_M = np.eye(2, dtype=complex)
    k0 = _key(start_M)
    found[k0] = ()
    q = deque([(start_M, ())])
    while q:
        M, word = q.popleft()
        if len(word) >= 6:
            continue
        for g in gens:
            M2 = mats[g] @ M
            k2 = _key(M2)
            if k2 not in found:
                found[k2] = word + (g,)
                q.append((M2, word + (g,)))
    return found


_CLIFFORD_TABLE = _build_clifford_table()
_CLIFFORD_ITEMS = None


def _clifford_items():
    global _CLIFFORD_ITEMS
    if _CLIFFORD_ITEMS is None:
        items = []
        for key, word in _CLIFFORD_TABLE.items():
            M = np.eye(2, dtype=complex)
            for g in word:
                M = _gate_matrix(g) @ M
            items.append((word, M))
        _CLIFFORD_ITEMS = items
    return _CLIFFORD_ITEMS


def _cost_of_word(word):
    return sum(1 for w in word if w in ("t", "tdg"))


def _try_clifford_or_clifford_t(U):
    best = None
    T = _gate_matrix("t")
    Tdg = _gate_matrix("tdg")

    def consider(word):
        nonlocal best
        if word is None:
            return
        cost = _cost_of_word(word)
        if best is None or cost < best[1]:
            best = (word, cost)

    key = _key(U)
    if key is not None and key in _CLIFFORD_TABLE:
        consider(list(_CLIFFORD_TABLE[key]))

    key = _key(U @ Tdg)
    if key is not None and key in _CLIFFORD_TABLE:
        consider(list(_CLIFFORD_TABLE[key]) + ["t"])
    key = _key(U @ T)
    if key is not None and key in _CLIFFORD_TABLE:
        consider(list(_CLIFFORD_TABLE[key]) + ["tdg"])
    key = _key(Tdg @ U)
    if key is not None and key in _CLIFFORD_TABLE:
        consider(["t"] + list(_CLIFFORD_TABLE[key]))
    key = _key(T @ U)
    if key is not None and key in _CLIFFORD_TABLE:
        consider(["tdg"] + list(_CLIFFORD_TABLE[key]))

    return best


def _normalize_theta(theta):
    t = theta % (2 * math.pi)
    if t > math.pi:
        t -= 2 * math.pi
    return t


def _rz_word_for_multiple_of_pi4(theta, tol=1e-7):
    k = round(theta / (math.pi / 4))
    if abs(theta / (math.pi / 4) - k) < tol:
        k = k % 8
        mapping = {
            0: [], 1: ["t"], 2: ["s"], 3: ["s", "t"],
            4: ["z"], 5: ["z", "t"], 6: ["sdg"], 7: ["tdg"],
        }
        return mapping[k]
    return None


def _try_single_rz_sandwich(U):
    """U = C1 * Rz(theta) * C2 up to global phase. Search C1,C2 over the 24-element
    Clifford table; accept the candidate giving a diagonal residual (up to global phase)
    with minimal total extra-gate cost."""
    best = None
    items = _clifford_items()
    for w1, M1 in items:
        M1inv = M1.conj().T
        for w2, M2 in items:
            M2inv = M2.conj().T
            cand = M1inv @ U @ M2inv
            # normalize by removing global phase using the larger-magnitude diagonal entry
            if abs(cand[0, 1]) > 1e-6 or abs(cand[1, 0]) > 1e-6:
                continue
            if abs(cand[0, 0]) < 1e-9 or abs(cand[1, 1]) < 1e-9:
                continue
            theta = _normalize_theta(2 * (cmath.phase(cand[1, 1]) - cmath.phase(cand[0, 0])))
            rz_word = _rz_word_for_multiple_of_pi4(theta)
            if rz_word is not None:
                mid_cost_t = _cost_of_word(rz_word)
                n_arb = 0
            else:
                mid_cost_t = 0
                n_arb = 1
            total_t = _cost_of_word(w1) + _cost_of_word(w2) + mid_cost_t
            total_len = len(w1) + len(w2) + (len(rz_word) if rz_word is not None else 1)
            cand_res = (w1, None if rz_word is not None else theta, rz_word, w2, n_arb, total_t, total_len)
            if best is None or (n_arb, total_t, total_len) < (best[4], best[5], best[6]):
                best = cand_res
    return best


def _emit_from_sandwich(best, qubit):
    w1, theta, rz_word, w2, _n_arb, _t, _len = best
    gates = []
    for g in w2:
        gates.append(Gate(g, (qubit,)))
    if rz_word is not None:
        for g in rz_word:
            gates.append(Gate(g, (qubit,)))
    else:
        gates.append(Gate("rz", (qubit,), theta=theta))
    for g in w1:
        gates.append(Gate(g, (qubit,)))
    return gates


def _matrix_of_run(names_thetas):
    U = np.eye(2, dtype=complex)
    for name, theta in names_thetas:
        g = Gate("rz", (0,), theta=theta) if name == "rz" else Gate(name, (0,))
        U = matrix(g) @ U
    return U


def _matrix_of_gates(gates):
    U = np.eye(2, dtype=complex)
    for g in gates:
        gg = Gate("rz", (0,), theta=g.theta) if g.name == "rz" else Gate(g.name, (0,))
        U = matrix(gg) @ U
    return U


def _cost_of_gatelist(gatelist_names_thetas):
    """(n_arbitrary_rz, n_T_like) using the real predicates, so it matches what the
    final gridsynth/T-count pass will see."""
    n_t = 0
    n_arb = 0
    for name, theta in gatelist_names_thetas:
        if name == "rz":
            g = Gate("rz", (0,), theta=theta)
            if is_arbitrary_rz(g):
                n_arb += 1
            elif is_t_like(g):
                n_t += 1
        elif name in ("t", "tdg"):
            n_t += 1
    return n_arb, n_t


def _is_close_phase(a, b, tol=1e-5):
    idx = np.unravel_index(np.argmax(np.abs(a)), a.shape)
    pa, pb = a[idx], b[idx]
    if abs(pa) < 1e-12 or abs(pb) < 1e-12:
        return np.allclose(a, b, atol=tol)
    return np.allclose(a / pa, b / pb, atol=tol)


def _process_run(names_thetas, qubit):
    """Return a cheaper exact replacement gate list for this run, else None."""
    orig_arb, orig_t = _cost_of_gatelist(names_thetas)
    if orig_arb == 0 and orig_t <= 1:
        return None  # already minimal-or-better; nothing to gain

    U = _matrix_of_run(names_thetas)

    candidates = []

    res = _try_clifford_or_clifford_t(U)
    if res is not None:
        word, _cost = res
        candidates.append([Gate(g, (qubit,)) for g in word])

    best = _try_single_rz_sandwich(U)
    if best is not None:
        candidates.append(_emit_from_sandwich(best, qubit))

    if not candidates:
        return None

    def score(gates):
        nt = [(g.name, g.theta) for g in gates]
        a_, t_ = _cost_of_gatelist(nt)
        return (a_, t_, len(gates))

    best_gates = min(candidates, key=score)
    best_arb, best_t = score(best_gates)[:2]

    if (best_arb, best_t, len(best_gates)) < (orig_arb, orig_t, len(names_thetas)):
        U_new = _matrix_of_gates(best_gates)
        if _is_close_phase(U, U_new):
            return best_gates
    return None


def rewrite(c: Circuit):
    gates = c.gates
    n = len(gates)
    out_gates = []
    i = 0
    changed_any = False

    while i < n:
        g = gates[i]
        if g.name in _SINGLE_Q_NAMES and g.cond is None and len(g.qubits) == 1:
            q = g.qubits[0]
            run_idxs = []
            j = i
            while j < n:
                gj = gates[j]
                if q in gj.qubits:
                    if gj.name in _SINGLE_Q_NAMES and gj.cond is None and len(gj.qubits) == 1:
                        run_idxs.append(j)
                        j += 1
                        continue
                    else:
                        break
                else:
                    j += 1
                    continue

            if len(run_idxs) >= 2:
                names_thetas = [(gates[k].name, gates[k].theta) for k in run_idxs]
                new_run = _process_run(names_thetas, q)
                run_set = set(run_idxs)
                last_run_idx = run_idxs[-1]
                # gates strictly within [i, last_run_idx] that are NOT part of the run
                # touch other qubits (since the run collects every consecutive gate that
                # touches q); they commute freely with the (reordered) run on q, so it is
                # safe to emit them before the compressed/unchanged run as a block.
                interleaved = [gates[k] for k in range(i, last_run_idx + 1) if k not in run_set]
                if new_run is not None:
                    out_gates.extend(interleaved)
                    out_gates.extend(new_run)
                    changed_any = True
                else:
                    out_gates.extend(interleaved)
                    for k in run_idxs:
                        out_gates.append(gates[k])
                i = last_run_idx + 1
                continue
        out_gates.append(g)
        i += 1

    if not changed_any:
        return c, Req()

    new_c = Circuit(c.n, out_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)

"""
conjugated_rz_pair_phase_gadget_merge

Canonicalises maximal runs of {cx, rz, t, tdg, s, sdg, z} (over ALL qubits, so no scope
tracking is needed) into the CNOT-parity phase-gadget picture: each qubit's running parity
(an XOR-mask of original wire indices) is tracked through the cx gates in the run, and every
diagonal phase gate seen is logged against the parity mask of the qubit it currently sits on.
Diagonal phase gates on the same parity mask commute through every intervening cx in the run
(a cx cannot change the Z-parity operator Z_m once m is fixed as a bitmask of original wires;
it only relabels which physical qubit currently carries that parity), so all phase contributions
to a given mask can be freely slid together and fused into one gate at the position of the first
occurrence: t+t->s, t+tdg->I, tdg+tdg->sdg, etc. (full mod-16 quarter-turn fusion). This is an
exact rewrite of the diagonal part of the block only; the cx skeleton (the free Clifford frame)
is left untouched, so the whole thing is an exact (eps=0) identity, verified by direct
replacement of the touched sub-block.
"""
from __future__ import annotations

from circuitevolve.circuit import Circuit, Gate, PI
from circuitevolve.verifier import Req

_TOL = 1e-7


def _quarter(theta, tol=_TOL):
    k = theta / (PI / 4)
    r = round(k)
    if abs(k - r) < tol:
        return int(r) % 16
    return None


def _angle_from_quarters(q):
    return (q % 16) * (PI / 4)


def _is_diag_phase(g: Gate):
    return g.name in ("rz", "t", "tdg", "s", "sdg", "z")


def _gate_quarters(g: Gate):
    if g.name == "t":
        return 1
    if g.name == "tdg":
        return -1
    if g.name == "s":
        return 2
    if g.name == "sdg":
        return -2
    if g.name == "z":
        return 4
    return None


def _make_gate_from_quarters(qbit, q):
    q = q % 16
    if q == 0:
        return []
    if q == 8:
        return [Gate("z", (qbit,))]
    if q == 4:
        return [Gate("s", (qbit,))]
    if q == 12:
        return [Gate("sdg", (qbit,))]
    if q == 2:
        return [Gate("t", (qbit,))]
    if q == 14:
        return [Gate("tdg", (qbit,))]
    if q == 6:
        return [Gate("s", (qbit,)), Gate("t", (qbit,))]
    if q == 10:
        return [Gate("sdg", (qbit,)), Gate("tdg", (qbit,))]
    return [Gate("rz", (qbit,), theta=_angle_from_quarters(q))]


def _find_block_end(gates, start, n):
    """Maximal run starting at `start` of cx (any qubits) and diagonal phase gates
    (rz/t/tdg/s/sdg/z), all with cond=None. Any other gate ends the run."""
    i = start
    m = len(gates)
    while i < m:
        g = gates[i]
        if g.cond is not None:
            break
        if g.name == "cx" or _is_diag_phase(g):
            i += 1
            continue
        break
    return i


def _process_block(gates, lo, hi, n):
    """Process gates[lo:hi] (a pure cx+diagonal-phase run over up to n qubits)."""
    sub = gates[lo:hi]
    parity = {q: frozenset([q]) for q in range(n)}
    mask_to_pos = {}
    result = []
    changed = False

    for g in sub:
        if g.name == "cx":
            a, b = g.qubits
            parity[b] = parity[a] ^ parity[b]
            result.append(("cx", a, b))
            continue
        qb = g.qubits[0]
        m = parity[qb]
        if g.name == "rz":
            q4 = _quarter(g.theta)
            if q4 is None:
                result.append(("rzraw", qb, g.theta))
                continue
        else:
            q4 = _gate_quarters(g)

        if m in mask_to_pos:
            pos = mask_to_pos[m]
            kind, old_q, old_mask, old_quarters = result[pos]
            new_quarters = (old_quarters + q4) % 16
            result[pos] = ("phase", qb, m, new_quarters)
            changed = True
        else:
            result.append(("phase", qb, m, q4 % 16))
            mask_to_pos[m] = len(result) - 1

    if not changed:
        return None

    out = []
    for entry in result:
        if entry[0] == "cx":
            _, a, b = entry
            out.append(Gate("cx", (a, b)))
        elif entry[0] == "rzraw":
            _, qb, theta = entry
            out.append(Gate("rz", (qb,), theta=theta))
        else:
            _, qb, m, q4 = entry
            out.extend(_make_gate_from_quarters(qb, q4))
    return out


def rewrite(c: Circuit):
    gates = list(c.gates)
    n = c.n
    total = len(gates)
    new_gates = []
    i = 0
    any_change = False

    while i < total:
        g = gates[i]
        if g.cond is None and (g.name == "cx" or _is_diag_phase(g)):
            end = _find_block_end(gates, i, total)
            if end > i + 1:
                block = _process_block(gates, i, end, n)
                if block is not None:
                    new_gates.extend(block)
                    any_change = True
                    i = end
                    continue
            new_gates.append(g)
            i += 1
            continue
        else:
            new_gates.append(g)
            i += 1

    if not any_change:
        return c, Req()

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)

"""
conjugated_rz_pair_phase_gadget_merge

Canonicalises maximal runs of {cx, rz, t, tdg, s, sdg, z} (restricted to runs where cond is
None) into the CNOT-parity phase-gadget picture: each qubit's running parity (an XOR-mask of
original wire indices, i.e. which original wires' Z operators, XORed together, the current
physical qubit's Z operator equals under the CX frame so far) is tracked through every cx in
the run, and every diagonal phase gate encountered is logged against the parity mask of the
qubit it currently sits on. A cx cannot change the operator Z_m for a fixed mask m -- it only
changes which physical wire currently carries that operator -- so every rz/t/tdg/s/sdg/z seen
on the same mask m commutes through all intervening cx gates in the run and can be freely
fused (mod 16 quarter turns) into a single gate, placed at the first occurrence of m and
re-expressed on whichever physical qubit holds m at that point. This is an exact identity on
the diagonal part of the block: the cx skeleton (free Clifford frame) is unchanged, only the
phase gates are re-associated and fused, so eps=0 and the block is checked by direct
replacement (sub-circuit equivalence) by the verifier.
"""
from __future__ import annotations

from circuitevolve.circuit import Circuit, Gate, PI
from circuitevolve.verifier import Req

_TOL = 1e-7


def _quarter(theta, tol=_TOL):
    k = theta / (PI / 4)
    r = round(k)
    if abs(k - r) < tol:
        return int(r) % 16
    return None


def _angle_from_quarters(q):
    return (q % 16) * (PI / 4)


def _is_diag_phase(g: Gate):
    return g.name in ("rz", "t", "tdg", "s", "sdg", "z")


def _gate_quarters(g: Gate):
    if g.name == "t":
        return 1
    if g.name == "tdg":
        return -1 % 16
    if g.name == "s":
        return 2
    if g.name == "sdg":
        return -2 % 16
    if g.name == "z":
        return 8
    return None


def _make_gate_from_quarters(qbit, q):
    q = q % 16
    table = {
        0: [],
        8: [Gate("z", (qbit,))],
        4: [Gate("s", (qbit,))],
        12: [Gate("sdg", (qbit,))],
        2: [Gate("t", (qbit,))],
        14: [Gate("tdg", (qbit,))],
        6: [Gate("s", (qbit,)), Gate("t", (qbit,))],
        10: [Gate("sdg", (qbit,)), Gate("tdg", (qbit,))],
    }
    if q in table:
        return table[q]
    return [Gate("rz", (qbit,), theta=_angle_from_quarters(q))]


def _find_block_end(gates, start, total):
    """Maximal run starting at `start` of cx and diagonal phase gates, all cond=None."""
    i = start
    while i < total:
        g = gates[i]
        if g.cond is not None:
            break
        if g.name == "cx" or _is_diag_phase(g):
            i += 1
            continue
        break
    return i


def _process_block(sub, n):
    """sub: list[Gate], a pure cx + diagonal-phase run (cond=None) over up to n qubits.
    Returns a replacement gate list, or None if nothing to fuse (no change)."""
    parity = {q: frozenset([q]) for q in range(n)}
    # entries: list of ("cx", a, b) or ["phase", qb, mask, quarters]  (mutable list for phase)
    result = []
    mask_to_idx = {}
    changed = False

    for g in sub:
        if g.name == "cx":
            a, b = g.qubits
            parity[b] = parity[a] ^ parity[b]
            result.append(("cx", a, b))
            continue

        qb = g.qubits[0]
        m = parity[qb]

        if g.name == "rz":
            q4 = _quarter(g.theta)
            if q4 is None:
                # arbitrary angle: cannot fuse symbolically into the quarter-turn table,
                # pass through untouched (it still occupies its own slot, no merging).
                result.append(("raw", qb, g.theta))
                continue
        else:
            q4 = _gate_quarters(g)

        if m in mask_to_idx:
            idx = mask_to_idx[m]
            entry = result[idx]
            # entry is ["phase", qb_at_first_occurrence, mask, quarters]
            entry[3] = (entry[3] + q4) % 16
            changed = True
        else:
            entry = ["phase", qb, m, q4 % 16]
            result.append(entry)
            mask_to_idx[m] = len(result) - 1

    if not changed:
        return None

    out = []
    for entry in result:
        if entry[0] == "cx":
            _, a, b = entry
            out.append(Gate("cx", (a, b)))
        elif entry[0] == "raw":
            _, qb, theta = entry
            out.append(Gate("rz", (qb,), theta=theta))
        else:
            _, qb, m, q4 = entry
            out.extend(_make_gate_from_quarters(qb, q4))
    return out


def rewrite(c: Circuit):
    gates = list(c.gates)
    n = c.n
    total = len(gates)
    new_gates = []
    i = 0
    any_change = False

    while i < total:
        g = gates[i]
        if g.cond is None and (g.name == "cx" or _is_diag_phase(g)):
            end = _find_block_end(gates, i, total)
            if end > i + 1:
                sub = gates[i:end]
                block = _process_block(sub, n)
                if block is not None:
                    new_gates.extend(block)
                    any_change = True
                    i = end
                    continue
            new_gates.append(g)
            i += 1
            continue
        else:
            new_gates.append(g)
            i += 1

    if not any_change:
        return c, Req()

    new_c = Circuit(c.n, new_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)

"""
euler_sx_rz_chain_collapse_to_single_rz

Scans each qubit wire for maximal runs of single-qubit unconditional unitary gates
(bounded by any gate touching that qubit with another qubit, by measure/reset/cond,
or by start/end of circuit), composes the exact 2x2 unitary of each run, and
re-emits it in a canonical minimal-T form: identity -> nothing; Clifford (up to
global phase, matched against the 24-element single-qubit Clifford group) -> a
short Clifford word with zero arbitrary rz; Clifford*Rz(theta)*Clifford -> that
triple with exactly one arbitrary rz; otherwise a 3-angle Rz-H-Rz-H-Rz Euler form
(at most 3 arbitrary rz, collapsing e.g. rz-sx-rz-sx-rz-...-rz runs of many more
rz's down to <=3). This is exact unitary-level fusion (matrix multiplication on
each wire), independent of and complementary to spider-based phase folding (which
cannot cross sx) and TKET/BQSKit single-qubit squashing (whose dyadic-phase-fixing
pass re-expands exactly these rz-sx-rz-sx-rz templates after TKET already ran).
Each replaced run is verified by exact 2x2 unitary equality (up to global phase),
so correctness follows directly from associativity of matrix multiplication.
"""
import math
from collections import deque

import numpy as np

from circuitevolve.circuit import Circuit, Gate, matrix, PI, _FIXED
from circuitevolve.verifier import Req

_TOL = 1e-7


def _phase_strip(U: np.ndarray) -> np.ndarray:
    for i, j in ((0, 0), (0, 1), (1, 0), (1, 1)):
        v = U[i, j]
        if abs(v) > 1e-12:
            return U * np.exp(-1j * np.angle(v))
    return U


def _mat1(name):
    return _FIXED[name].astype(complex)


def _build_clifford_table():
    H = _mat1("h")
    S = _mat1("s")
    gens = [("h", H), ("s", S)]

    def key(U):
        Us = _phase_strip(U.copy())
        return tuple(np.round(Us.flatten(), 6))

    seen = {}
    start_word = ()
    start_mat = np.eye(2, dtype=complex)
    q = deque()
    q.append((start_word, start_mat))
    seen[key(start_mat)] = (start_word, start_mat)
    while q:
        word, U = q.popleft()
        if len(word) > 6:
            continue
        for gname, G in gens:
            U2 = G @ U
            k = key(U2)
            if k not in seen:
                w2 = word + (gname,)
                seen[k] = (w2, U2)
                q.append((w2, U2))
    return list(seen.values())


_CLIFFORD_TABLE = _build_clifford_table()
assert len(_CLIFFORD_TABLE) == 24, f"expected 24 cosets, got {len(_CLIFFORD_TABLE)}"


def _match_clifford(U: np.ndarray):
    Us = _phase_strip(U.copy())
    best = None
    for word, M in _CLIFFORD_TABLE:
        if np.max(np.abs(_phase_strip(M.copy()) - Us)) < 1e-6:
            if best is None or len(word) < len(best):
                best = word
    return best


def _rz_angle_from_diag(Us: np.ndarray):
    if abs(Us[0, 1]) > 1e-6 or abs(Us[1, 0]) > 1e-6:
        return None
    a = np.angle(Us[1, 1]) - np.angle(Us[0, 0])
    while a <= -PI:
        a += 2 * PI
    while a > PI:
        a -= 2 * PI
    return a


def _try_clifford_rz_clifford(U: np.ndarray):
    """Search for U = C2 Rz(theta) C1 (C1 applied first) with C1,C2 Clifford."""
    best = None
    for w1, M1 in _CLIFFORD_TABLE:
        M1inv = M1.conj().T
        for w2, M2 in _CLIFFORD_TABLE:
            M2inv = M2.conj().T
            V = M2inv @ U @ M1inv
            Vs = _phase_strip(V.copy())
            theta = _rz_angle_from_diag(Vs)
            if theta is not None and abs(theta) > 1e-9:
                cand = (len(w1) + len(w2), w1, theta, w2)
                if best is None or cand[0] < best[0]:
                    best = cand
    if best is None:
        return None
    _, w1, theta, w2 = best
    return w1, theta, w2


def _zyz_canonical(U):
    """U (det=1, normalized) = Rz(c) Rx(b) Rz(a), a applied first. Rx(b)=H Rz(b) H."""
    m00, m01 = U[0, 0], U[0, 1]
    m11 = U[1, 1]
    cos_b2 = min(1.0, abs(m00))
    sin_b2 = min(1.0, abs(m01))
    b = 2 * math.atan2(sin_b2, cos_b2)
    if sin_b2 < 1e-9:
        a = 0.0
        c = 2 * np.angle(m11)
        return a, b, c
    if cos_b2 < 1e-9:
        a = 0.0
        c = -2 * (np.angle(m01) + math.pi / 2)
        return a, b, c
    ang11 = np.angle(m11)                      # = (c+a)/2
    ang01 = np.angle(m01) + math.pi / 2         # = (a-c)/2
    half_sum = ang11
    half_diff = ang01
    a = half_sum + half_diff
    c = half_sum - half_diff
    return a, b, c


def zxz_decompose(U: np.ndarray):
    det = np.linalg.det(U)
    Uu = U / (np.sqrt(det) + 0j) if abs(det) > 1e-12 else U
    return _zyz_canonical(Uu)


def _rz_gate(theta, q):
    return Gate("rz", (q,), theta=float(theta))


def _emit_clifford_word(word, q):
    return [Gate(name, (q,)) for name in word]


def _segment_matrix(gates_1q):
    U = np.eye(2, dtype=complex)
    for g in gates_1q:
        U = matrix(g) @ U
    return U


def _t_rz_cost(gate_list):
    """(num_arbitrary_rz, num_t_like, total_gates) for comparing candidate emissions."""
    from circuitevolve.circuit import is_arbitrary_rz, is_t_like
    rz = sum(is_arbitrary_rz(g) for g in gate_list)
    tl = sum(is_t_like(g) for g in gate_list)
    return (rz, tl, len(gate_list))


def _canonical_segment(U: np.ndarray, q: int):
    """Return minimal-cost gate list implementing U (up to global phase) on qubit q."""
    Us = _phase_strip(U.copy())
    if np.max(np.abs(Us - np.eye(2))) < 1e-7:
        return []

    candidates = []

    w = _match_clifford(U)
    if w is not None:
        candidates.append(_emit_clifford_word(w, q))

    cliff_rz = _try_clifford_rz_clifford(U)
    if cliff_rz is not None:
        w1, theta, w2 = cliff_rz
        out = _emit_clifford_word(w1, q)
        out.append(_rz_gate(theta, q))
        out.extend(_emit_clifford_word(w2, q))
        candidates.append(out)

    a, b, c = zxz_decompose(U)
    out = []
    if abs(a) > 1e-9:
        out.append(_rz_gate(a, q))
    out.append(Gate("h", (q,)))
    if abs(b) > 1e-9:
        out.append(_rz_gate(b, q))
    out.append(Gate("h", (q,)))
    if abs(c) > 1e-9:
        out.append(_rz_gate(c, q))
    candidates.append(out)

    candidates.sort(key=_t_rz_cost)
    return candidates[0]


def _verify_segment(seg_gates, new_gates, q):
    """Exact unitary check up to global phase."""
    U_old = _segment_matrix(seg_gates)
    U_new = np.eye(2, dtype=complex)
    for g in new_gates:
        U_new = matrix(g) @ U_new
    return np.max(np.abs(_phase_strip(U_old.copy()) - _phase_strip(U_new.copy()))) < 1e-6


def rewrite(c: Circuit):
    gates = c.gates
    n = c.n
    N = len(gates)

    pending = {q: [] for q in range(n)}
    segments = []  # (idxs_list, new_gates)

    from circuitevolve.circuit import is_arbitrary_rz, is_t_like

    def flush(q):
        idxs = pending[q]
        if len(idxs) >= 2:
            seg_gates = [gates[i] for i in idxs]
            old_cost = (
                sum(is_arbitrary_rz(g) for g in seg_gates),
                sum(is_t_like(g) for g in seg_gates),
                len(seg_gates),
            )
            U = _segment_matrix(seg_gates)
            new_gates = _canonical_segment(U, q)
            new_cost = (
                sum(is_arbitrary_rz(g) for g in new_gates),
                sum(is_t_like(g) for g in new_gates),
                len(new_gates),
            )
            if new_cost < old_cost and _verify_segment(seg_gates, new_gates, q):
                segments.append((idxs, new_gates))
        pending[q] = []

    for i, g in enumerate(gates):
        is_1q_unitary_unconditional = (
            g.cond is None and g.name not in ("measure", "reset") and len(g.qubits) == 1
        )
        if is_1q_unitary_unconditional:
            pending[g.qubits[0]].append(i)
        else:
            for qq in g.qubits:
                flush(qq)
    for q in range(n):
        flush(q)

    if not segments:
        return c, Req()

    remove_idx = set()
    insert_at_first = {}
    for idxs, new_gates in segments:
        insert_at_first[idxs[0]] = new_gates
        for j in idxs:
            remove_idx.add(j)

    out_gates = []
    for i, g in enumerate(gates):
        if i in insert_at_first:
            out_gates.extend(insert_at_first[i])
        if i in remove_idx:
            continue
        out_gates.append(g)

    new_c = Circuit(c.n, out_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)

