        fresh_counter[0] += 1
        return frozenset({fresh_counter[0]})

    parity = {q: fresh_vec() for q in range(n)}

    groups = {}  # (parity_vector, round(|delta|/_BIN)) -> list of (index, theta)

    for i, g in enumerate(new_gates):
        if g.name == "cx":
            ctrl, tgt = g.qubits
            if ctrl not in parity:
                parity[ctrl] = fresh_vec()
            if tgt not in parity:
                parity[tgt] = fresh_vec()
            parity[tgt] = parity[tgt].symmetric_difference(parity[ctrl])
        elif g.name in _Z_DIAGONAL:
            q = g.qubits[0]
            if q not in parity:
                parity[q] = fresh_vec()
            # transparent: parity unchanged
        elif g.name == "rz":
            q = g.qubits[0]
            if q not in parity:
                parity[q] = fresh_vec()
            if i in rz_pos_set:
                bucket = round(abs(g.theta) / _BIN)
                key = (parity[q], bucket)
                groups.setdefault(key, []).append((i, g.theta, q))
            # transparent: parity unchanged (rz is diagonal)
        elif g.name in _BASIS_RESET:
            q = g.qubits[0]
            parity[q] = fresh_vec()
        elif g.name in ("cz", "swap", "ccx", "ccz"):
            for q in g.qubits:
                parity[q] = fresh_vec()
        elif g.name in ("measure", "reset"):
            for q in g.qubits:
                parity[q] = fresh_vec()
        else:
            for q in g.qubits:
                parity[q] = fresh_vec()

    # Step 3: merge/cancel within each group.
    to_delete = set()
    to_retheta = {}

    for key, entries in groups.items():
        if len(entries) < 2:
            continue
        total = sum(theta for _, theta, _ in entries)
        indices = [idx for idx, _, _ in entries]
        if abs(total) < _TOL:
            for idx in indices:
                to_delete.add(idx)
        else:
            keep = indices[-1]
            for idx in indices[:-1]:
                to_delete.add(idx)
            to_retheta[keep] = total

    if not to_delete and not to_retheta:
        return c, Req()

    final_gates = []
    for i, g in enumerate(new_gates):
        if i in to_delete:
            continue
        if i in to_retheta:
            newtheta = to_retheta[i]
            if abs(newtheta) < _TOL:
                continue
            final_gates.append(replace(g, theta=newtheta))
        else:
            final_gates.append(g)

    new_c = Circuit(c.n, final_gates, c.nc, c.zero_init)
    return new_c, Req(eps=0.0, ancillas=0, measure=False)
